// store
import { type } from '../../../shared/utility/utilityHelpers';
export const ActionTypes = {
  DOWNLOAD_FILE: type('[Import] Download File'),
  DOWNLOAD_FILE_SUCCESS: type('[Import] Download File Success'),
  DOWNLOAD_FILE_FAIL: type('[Import] Download File Fail'),
  UPLOAD_FILE: type('[Import] Upload File'),
  UPLOAD_FILE_SUCCESS: type('[Import] Upload File Success'),
  UPLOAD_FILE_FAIL: type('[Import] Upload File Fail')
}; // Download File

export class DownloadFileAction {
  constructor(payload = null) {
    this.payload = payload;
    this.type = ActionTypes.DOWNLOAD_FILE;
  }

}
export class DownloadFileSuccessAction {
  constructor(payload) {
    this.payload = payload;
    this.type = ActionTypes.DOWNLOAD_FILE_SUCCESS;
  }

}
export class DownloadFileFailAction {
  constructor(payload = null) {
    this.payload = payload;
    this.type = ActionTypes.DOWNLOAD_FILE_FAIL;
  }

} // Upload File

export class UploadFileAction {
  constructor(payload) {
    this.payload = payload;
    this.type = ActionTypes.UPLOAD_FILE;
  }

}
export class UploadFileSuccessAction {
  constructor(payload) {
    this.payload = payload;
    this.type = ActionTypes.UPLOAD_FILE_SUCCESS;
  }

}
export class UploadFileFailAction {
  constructor(payload = null) {
    this.payload = payload;
    this.type = ActionTypes.UPLOAD_FILE_FAIL;
  }

}
